#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;

    const long long MOD = 1000000007;
    vector<long long> ways(n + 1, 0);
    ways[0] = 1;
    for (long long i = 1; i <= n; i++) {
        long long total = ways[i - 1];
        if (i >= 2) total += ways[i - 2];
        if (i >= 3) total += ways[i - 3];
        ways[i] = total % MOD;
    }
    cout << ways[n] << "\n";

    return 0;
}

